import { composeDraft, getBlock, nextAutofillBlock, register } from "@/tenor-engine";
import type { Draft, Profile } from "@/tenor-types";
import { lottoDemoCases, type DemoCase } from "@/data/lottoDemoCases";
import {
  assessCompleteness,
  filterModeCommands,
  inferFallgruppe,
