from __future__ import annotations

import json
import tempfile
import unittest
from pathlib import Path

from fastapi.testclient import TestClient

from muclegal.live import LiveMonitorWorkflow
from muclegal.llm.tenor import (
    DeterministicTenorAnalyzer,
    OpenAITenorAnalyzer,
    TENOR_PROMPT_SHA256,
    TENOR_PROMPT_VERSION,
    TenorDraftValidationError,
    build_tenor_input,
    create_tenor_draft,
    create_tenor_proposals,
    validate_tenor_draft,
)
from muclegal.ui import create_app


ROOT = Path(__file__).resolve().parents[1]


def tenor_payload() -> dict:
    return {
        "fall_id": "VZ-TEST-001",
        "schuldner": "Synthetische Beispiel GmbH",
        "fundstelle": "https://example.org/angebot",
        "beschreibung": "mit einer nicht bestehenden Befristung zu werben",
        "rechtsgrundlagen": ["§ 5 UWG", "§ 8 Abs. 1 UWG"],
    }


class StrategyTenorAnalyzer(DeterministicTenorAnalyzer):
    mode = "test_openai"
    model = "test-model"

    def analyze(self, model_input: dict) -> dict:
        value = super().analyze(model_input)
        strategy = model_input["strategie"]["id"]
        value["entwurf"] = f"{value['entwurf']} Strategie: {strategy}."
        return value


class TenorDraftTests(unittest.TestCase):
    def test_tenor_prompt_is_separately_versioned(self) -> None:
        self.assertEqual("2026-08-19-tenor-draft-1", TENOR_PROMPT_VERSION)
        self.assertEqual(64, len(TENOR_PROMPT_SHA256))

    def test_deterministic_draft_is_valid_and_not_human_approved(self) -> None:
        model_input = build_tenor_input(**tenor_payload())
        draft, mode, _ = create_tenor_draft(model_input, DeterministicTenorAnalyzer())
        self.assertEqual("deterministic_demo", mode)
        self.assertIsNone(draft.freigabe_durch_mensch)
        self.assertTrue(draft.nicht_umfasst)
        self.assertEqual(tuple(model_input["rechtsgrundlagen"]), draft.rechtsgrundlagen)

    def test_unproven_legal_source_and_model_release_are_rejected(self) -> None:
        model_input = build_tenor_input(**tenor_payload())
        value = DeterministicTenorAnalyzer().analyze(model_input)
        value["rechtsgrundlagen"].append("§ 890 ZPO")
        with self.assertRaises(TenorDraftValidationError):
            validate_tenor_draft(value, allowed_legal_bases=model_input["rechtsgrundlagen"])

    def test_two_proposals_are_case_specific_and_require_human_review(self) -> None:
        model_input = build_tenor_input(**tenor_payload())
        result = create_tenor_proposals(
            model_input,
            StrategyTenorAnalyzer(),
            fallgruppe="irrefuehrende_werbung",
        )
        self.assertEqual("test_openai", result["mode"])
        self.assertEqual(["precise", "neutral"], [item["strategy"] for item in result["proposals"]])
        self.assertNotEqual(result["proposals"][0]["text"], result["proposals"][1]["text"])
        self.assertTrue(all(item["human_approval_required"] for item in result["proposals"]))
        self.assertTrue(all(item["freigabe_durch_mensch"] is None for item in result["proposals"]))

    def test_openai_analyzer_uses_frozen_prompt_and_structured_output(self) -> None:
        class FakeResponses:
            def __init__(self) -> None:
                self.request = None

            def create(self, **kwargs):
                self.request = kwargs
                value = DeterministicTenorAnalyzer().analyze(tenor_payload() | {
                    "beschreibung": tenor_payload()["beschreibung"],
                })
                return type(
                    "Response",
                    (),
                    {"status": "completed", "output_text": json.dumps(value)},
                )()

        responses = FakeResponses()
        client = type("Client", (), {"responses": responses})()
        analyzer = OpenAITenorAnalyzer(model="test-model", client=client)
        analyzer.analyze(build_tenor_input(**tenor_payload()))
        self.assertEqual("test-model", responses.request["model"])
        self.assertIn("prüfbedürftigen Entwurf", responses.request["instructions"])
        self.assertTrue(responses.request["text"]["format"]["strict"])
        self.assertFalse(responses.request["store"])
        value = DeterministicTenorAnalyzer().analyze(model_input)
        value["freigabe_durch_mensch"] = "freigegeben"
        with self.assertRaises(TenorDraftValidationError):
            validate_tenor_draft(value, allowed_legal_bases=model_input["rechtsgrundlagen"])

    def test_api_requires_human_review_before_workflow_uses_draft(self) -> None:
        with tempfile.TemporaryDirectory() as output:
            root = Path(output)
            workflow = LiveMonitorWorkflow(root, ROOT / "fixtures" / "tenor.json")
            original = workflow.tenor["fall_id"]
            app = create_app(
                workflow.latest_case_path,
                root / "reviews.sqlite3",
                workflow=workflow,
                anthropic_ready=True,
                asset_directory=ROOT / "assets",
            )
            with TestClient(app) as client:
                created = client.post("/api/tenor-drafts", json=tenor_payload())
                self.assertEqual(201, created.status_code, created.text)
                record = created.json()
                self.assertEqual(original, workflow.tenor["fall_id"])
                approved = client.post(
                    f"/api/tenor-drafts/{record['draft_id']}/review",
                    json={"decision": "freigegeben"},
                )
                self.assertEqual(200, approved.status_code, approved.text)
            self.assertEqual("VZ-TEST-001", workflow.tenor["fall_id"])
            saved = json.loads((root / "approved-tenor.json").read_text(encoding="utf-8"))
            self.assertEqual("VZ-TEST-001", saved["fall_id"])
            restarted = LiveMonitorWorkflow(root, ROOT / "fixtures" / "tenor.json")
            self.assertEqual("VZ-TEST-001", restarted.tenor["fall_id"])

    def test_tenor_api_rejects_unknown_fields(self) -> None:
        with tempfile.TemporaryDirectory() as output:
            root = Path(output)
            workflow = LiveMonitorWorkflow(root, ROOT / "fixtures" / "tenor.json")
            app = create_app(
                workflow.latest_case_path,
                root / "reviews.sqlite3",
                workflow=workflow,
                anthropic_ready=True,
            )
            payload = {**tenor_payload(), "freigabe_durch_mensch": "freigegeben"}
            with TestClient(app) as client:
                response = client.post("/api/tenor-drafts", json=payload)
            self.assertEqual(422, response.status_code)


if __name__ == "__main__":
    unittest.main()

import { Link } from "@tanstack/react-router";
import {
  ArrowLeft,
  Check,
  FileUp,
  Keyboard,
  Loader2,
  Mic,
  RotateCcw,
  Sparkles,
  X,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";

import { composeDraft, getBlock, nextAutofillBlock, register } from "@/tenor-engine";
import type { Draft, Profile } from "@/tenor-types";
import { lottoDemoCases, type DemoCase } from "@/data/lottoDemoCases";
import {
  assessCompleteness,
  filterModeCommands,
  inferFallgruppe,
  isTenor,
  modeCommands,
  nextWrappedIndex,
  type WritingMode,
} from "@/lib/minimal-tenor-logic";
import {
  createTenorProposals,
  type TenorProposalResponse,
} from "@/lib/tenor-api";

const baseProfile: Profile = {
  profilId: "V-2026-014",
  schuldner: "die Beklagte",
  rechtsform: "GmbH",
  kanal: ["website"],
  url: "https://www.beispiel.de",
  adressat: "verbraucher",
  vertragstyp: "dauerschuldverhaeltnis",
  fallgruppe: "kuendigungsbutton",
  verstossModus: "vorhanden_unzureichend",
  rechtsgrundlage: ["§ 2 Abs. 1 UKlaG", "§ 312k Abs. 2 BGB", "§ 890 ZPO"],
  beanstandeterWortlaut: "",
  wirkung: "",
  bekannteUmgehungen: [],
  gestaltungsmerkmale: ["Gestaltung", "Wirkung"],
  anlage: "K 1",
};

type SpeechResult = { readonly transcript: string };
type SpeechResultList = {
  readonly length: number;
  [index: number]: { [index: number]: SpeechResult };
};
type SpeechEvent = { readonly results: SpeechResultList };
type SpeechRecognitionInstance = {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  onresult: ((event: SpeechEvent) => void) | null;
  onend: (() => void) | null;
  start: () => void;
  stop: () => void;
};
type SpeechRecognitionConstructor = new () => SpeechRecognitionInstance;
function caseContext(selectedCase: DemoCase) {
  return `${selectedCase.fall_id}: ${selectedCase.title}. ${selectedCase.secondary}. ${selectedCase.explanation} Fundstelle: ${selectedCase.evidence.fundstelle}.`;
}

function profileFromContext(context: string): Profile {
  const lower = context.toLowerCase();
  const fallgruppe = inferFallgruppe(lower);
  const verstossModus =
    fallgruppe === "agb_klausel"
      ? "klausel_verwendet"
      : fallgruppe === "kuendigungsbutton"
        ? "vorhanden_unzureichend"
        : "irrefuehrend_gestaltet";
  const url = context.match(/https?:\/\/[^\s,;)]+/i)?.[0] ?? baseProfile.url;
  return {
    ...baseProfile,
    fallgruppe,
    verstossModus,
    url,
    kanal: /\bapp\b/i.test(context) ? ["website", "app"] : ["website"],
    beanstandeterWortlaut: fallgruppe === "agb_klausel" ? context.slice(0, 500) : "",
    wirkung: context.slice(0, 500),
  };
}

function legalBasesFor(fallgruppe: string) {
  if (fallgruppe === "agb_klausel") return ["§ 1 UKlaG"];
  if (fallgruppe === "irrefuehrende_werbung") return ["§ 5 UWG", "§ 8 Abs. 1 UWG"];
  if (fallgruppe === "consent_gestaltung") return ["§ 25 Abs. 1 TDDDG", "§ 2 Abs. 1 UKlaG"];
  if (fallgruppe === "dark_pattern_dsa") return ["Art. 25 DSA", "§ 2 Abs. 1 UKlaG"];
  return ["§ 312k Abs. 2 BGB", "§ 2 Abs. 1 UKlaG"];
}

function debtorFromContext(context: string) {
  const match = context.match(
    /\b([A-ZÄÖÜ][A-Za-zÄÖÜäöüß0-9&.,' -]{1,100}\s(?:GmbH|AG|UG|SE|KG|e\.\s?K\.))\b/,
  );
  return match?.[1]?.trim() ?? "die Antragsgegnerin";
}

function aiProvenance(response: TenorProposalResponse | null, strategy: "precise" | "neutral") {
  const proposal = response?.proposals.find((item) => item.strategy === strategy);
  if (!response || !proposal) return null;
  return `OpenAI ${response.model} · ${proposal.source_ids.join(" · ")} · nicht juristisch freigegeben`;
}

function referenceSummary(draft: Draft) {
  const references = [...new Set(draft.blockIds.flatMap((id) => getBlock(id).belegt_in))];
  return `${draft.blockIds.join(" · ")}  —  ${references
    .map((id) => {
      const tenor = register.tenore.find((item) => item.id === id);
      return tenor?.zitat_geprueft === true ? id : `${id} ungeprüft`;
    })
    .join(" · ")}`;
}

function DraftChoice({
  title,
  draft,
  text,
  selected,
  onSelect,
  onText,
  provenance,
}: {
  title: string;
  draft: Draft;
  text: string;
  selected: boolean;
  onSelect: () => void;
  onText: (text: string) => void;
  provenance?: string | null;
}) {
  return (
    <div className="flex min-w-0 flex-col px-1 py-4 md:min-h-0 md:px-6 md:py-1">
      <button type="button" onClick={onSelect} className="flex items-center gap-3 text-left">
        <span
          className={`grid size-5 place-items-center rounded-full border ${selected ? "border-slate-950 bg-slate-950" : "border-slate-300"}`}
        >
          {selected && <Check className="size-3 text-white" />}
        </span>
        <span className="text-sm font-semibold text-slate-900">{title}</span>
      </button>
      <textarea
        value={text}
        onFocus={onSelect}
        onChange={(event) => onText(event.target.value)}
        aria-label={`${title} bearbeiten`}
        className="mt-3 min-h-48 w-full resize-none overflow-y-auto bg-transparent font-serif text-sm leading-6 text-slate-700 outline-none md:min-h-0 md:flex-1"
      />
      <p className="mt-3 break-words font-mono text-[9px] leading-4 text-slate-300">
        {provenance ?? referenceSummary(draft)}
      </p>
    </div>
  );
}

export function MinimalTenorView() {
  const [context, setContext] = useState("");
  const [mode, setMode] = useState<WritingMode | null>(null);
  const [selectedCase, setSelectedCase] = useState<DemoCase | null>(null);
  const [commandIndex, setCommandIndex] = useState(0);
  const [caseIndex, setCaseIndex] = useState(0);
  const [pdf, setPdf] = useState<File | null>(null);
  const [dragging, setDragging] = useState(false);
  const [dictating, setDictating] = useState(false);
  const [dictationNotice, setDictationNotice] = useState("");
  const [generating, setGenerating] = useState(false);
  const [generated, setGenerated] = useState(false);
  const [selected, setSelected] = useState<"precise" | "neutral" | null>(null);
  const [preciseText, setPreciseText] = useState("");
  const [neutralText, setNeutralText] = useState("");
  const [proposalResponse, setProposalResponse] = useState<TenorProposalResponse | null>(null);
  const [generationError, setGenerationError] = useState("");
  const [acceptedIds, setAcceptedIds] = useState<string[]>([]);
  const [suggestion, setSuggestion] = useState<ReturnType<typeof nextAutofillBlock>>(null);
  const fileInput = useRef<HTMLInputElement>(null);
  const contextInput = useRef<HTMLTextAreaElement>(null);
  const speech = useRef<SpeechRecognitionInstance | null>(null);

  const profile = useMemo(() => profileFromContext(context), [context]);
  const preciseDraft = useMemo(() => composeDraft(profile, "eng"), [profile]);
  const neutralDraft = useMemo(() => composeDraft(profile, "kerngleich"), [profile]);
  const contextLength = context.trim().length;
